import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"NetPilot: un binario, todas las respuestas","description":"La historia de construir NetPilot — un kit de red en Go puro que comprime cinco herramientas de admin en un solo binario estático.","frontmatter":{"title":"NetPilot: un binario, todas las respuestas","description":"La historia de construir NetPilot — un kit de red en Go puro que comprime cinco herramientas de admin en un solo binario estático."},"headers":[],"relativePath":"es/vibe-stories/story-1/index.md","filePath":"es/vibe-stories/story-1/index.md"}`),a={name:`es/vibe-stories/story-1/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="netpilot-un-binario-todas-las-respuestas" tabindex="-1">NetPilot: un binario, todas las respuestas <a class="header-anchor" href="#netpilot-un-binario-todas-las-respuestas" aria-label="Permalink to “NetPilot: un binario, todas las respuestas”">​</a></h1><p>Todo sysadmin tiene esa carpeta de herramientas a medio instalar: una para escanear puertos, otra para ping, otra para health checks, todas con flags y formatos de salida distintos. <strong>NetPilot</strong> (<a href="https://github.com/Godde3s/netpilot" target="_blank" rel="noreferrer">GitHub</a>) empezó cuando me cansé de ser ese sysadmin.</p><h2 id="la-restriccion-que-le-dio-forma" tabindex="-1">La restricción que le dio forma <a class="header-anchor" href="#la-restriccion-que-le-dio-forma" aria-label="Permalink to “La restricción que le dio forma”">​</a></h2><p>Me di una sola regla: <strong>el entregable es un único binario estático</strong>. Sin runtime, sin dependencias, sin instalador. Esa única restricción decidió el lenguaje (Go), la arquitectura (stdlib primero) y la UX (subcomandos que se leen como frases). También convirtió al proyecto en el banco de pruebas perfecto para el desarrollo con equipo de agentes — la spec era lo bastante nítida para que los <a href="/Usf/es/agentic/overview/">agentes</a> implementaran comandos en paralelo mientras yo revisaba.</p><h2 id="lo-que-me-enseno-construirlo" tabindex="-1">Lo que me enseñó construirlo <a class="header-anchor" href="#lo-que-me-enseno-construirlo" aria-label="Permalink to “Lo que me enseñó construirlo”">​</a></h2><ul><li><strong>El diseño de concurrencia le gana al folclore de concurrencia</strong> — un pool de workers con timeouts reales superó a tres borradores &quot;optimizados&quot;.</li><li><strong>El output es una API</strong> — una salida JSON estable convirtió el CLI en un bloque que otros scripts (y agentes) pueden consumir.</li><li><strong>La contención escala</strong> — cinco comandos bien hechos valen más que treinta a medias.</li></ul><p>Hoy NetPilot es lo primero que despliego en cualquier máquina nueva, y el estándar con el que juzgo cada CLI que construyo — incluidos los que los agentes construyen para mí.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};